// https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax#alerts
// Five types:
// [!NOTE], [!TIP], [!WARNING], [!IMPORTANT], [!CAUTION]
var gitHubAlertRe = regexp.MustCompile(`^<p>\[!(NOTE|TIP|WARNING|IMPORTANT|CAUTION)\]`)

// resolveGitHubAlert returns one of note, tip, warning, important or caution.
// An empty string if no match.
func (r *htmlRenderer) resolveGitHubAlert(cap *render.BlockquoteCapture, bqctx *blockquoteContext) string {
	ctx := cap.Context()
	pos := ctx.PopPos()
	raw := string(ctx.Buffer.Bytes()[pos:])
	ctx.Buffer.Truncate(pos)
	bqctx.ordinal = ctx.GetAndIncrementOrdinal(ast.KindBlockquote)
	bqctx.text = hstring.RenderedString(raw)

	m := r.alertRe.FindStringSubmatch(string(bqctx.text))
	if len(m) == 2 {
		bqctx.alertType = strings.ToLower(m[1])
		bqctx.typ = typeAlert
		return bqctx.alertType
	}

	bqctx.alertType = ""
	bqctx.typ = r.fallbackType
	return bqctx.alertType
}

